CREATE TABLE IF NOT EXISTS projection_servicos_extras (
    id UUID PRIMARY KEY, codigo_academia VARCHAR(50) NOT NULL, nome VARCHAR(150) NOT NULL, descricao TEXT, categoria VARCHAR(100), pago BOOLEAN NOT NULL DEFAULT false, preco NUMERIC(14,2), tipo_cobranca VARCHAR(10) CHECK (tipo_cobranca IN ('unico','mensal')), metodos_pagamento TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], tem_taxa_inscricao BOOLEAN NOT NULL DEFAULT false, valor_taxa_inscricao NUMERIC(14,2), metodos_pagamento_taxa_inscricao TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], anos_academicos_disponiveis TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], documento_obrigatorio BOOLEAN NOT NULL DEFAULT false, documento_instrucoes TEXT, detalhes_personalizados JSONB NOT NULL DEFAULT '{}'::jsonb, ativo BOOLEAN NOT NULL DEFAULT true, criado_por UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, version INTEGER NOT NULL DEFAULT 0, last_event_id UUID,
    CONSTRAINT chk_servico_extra_pago_campos CHECK ((pago = false AND preco IS NULL AND tipo_cobranca IS NULL AND metodos_pagamento = ARRAY[]::TEXT[]) OR (pago = true AND preco IS NOT NULL AND preco > 0 AND tipo_cobranca IS NOT NULL AND array_length(metodos_pagamento,1) IS NOT NULL)),
    CONSTRAINT chk_servico_extra_taxa_campos CHECK ((tem_taxa_inscricao = false AND valor_taxa_inscricao IS NULL AND metodos_pagamento_taxa_inscricao = ARRAY[]::TEXT[]) OR (tem_taxa_inscricao = true AND valor_taxa_inscricao IS NOT NULL AND valor_taxa_inscricao > 0 AND array_length(metodos_pagamento_taxa_inscricao,1) IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_servicos_extras_academia ON projection_servicos_extras(codigo_academia);
CREATE INDEX IF NOT EXISTS idx_servicos_extras_ativo ON projection_servicos_extras(codigo_academia, ativo);
